FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 157: probes: fills with tangency conditions across a gap between sheets. Generated by tools/fixtures/gen-batch-157.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

// The fill's area, its point and normal at the middle of its parameters, and how far above (along z) it lies over
// points across the gap, rounded to 1e-6.
function fillProbe(context is Context, faces is Query) returns array
{
    var out = [];
    const r = function(x) { return round(x * 1e6) / 1e6; };
    for (var f in evaluateQuery(context, faces))
    {
        const p = evFaceTangentPlane(context, { "face" : f, "parameter" : vector(0.5, 0.5) });
        var heights = [];
        for (var x in [2.5, 5, 7.5])
        {
            for (var y in [5, 10])
            {
                const d = evDistance(context, { "side0" : f, "side1" : line(vector(x, y, 0) * millimeter, vector(0, 0, 1)) });
                heights = append(heights, r(d.sides[0].point[2] / millimeter));
            }
        }
        out = append(out, [r(evArea(context, { "entities" : f }) / millimeter ^ 2),
                [r(p.origin[0] / millimeter), r(p.origin[1] / millimeter), r(p.origin[2] / millimeter)],
                [r(p.normal[0]), r(p.normal[1]), r(p.normal[2])], heights]);
    }
    return out;
}

// fill: a gap between a level sheet and a rising one bridged by a fill tangent to both
export function c001(context is Context, id is Id)
{
    const aSketch = newSketchOnPlane(context, id + "aSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(-1, 0, 0), vector(0, 1, 0)) });
    skLineSegment(aSketch, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(20, 0) * millimeter });
    skSolve(aSketch);
    extrude(context, id + "a", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "aSketch", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter });
    const bSketch = newSketchOnPlane(context, id + "bSketch", { "sketchPlane" : plane(vector(10, 0, 5) * millimeter, vector(0.894427, 0, 0.447214), vector(0, 1, 0)) });
    skLineSegment(bSketch, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(20, 0) * millimeter });
    skSolve(bSketch);
    extrude(context, id + "b", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "bSketch", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter });
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(s1, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(10, 5) * millimeter });
    skSolve(s1);
    const s2 = newSketchOnPlane(context, id + "s2", { "sketchPlane" : plane(vector(0, 20, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(s2, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(10, 5) * millimeter });
    skSolve(s2);
    fill(context, id + "fill1", { "edges" : [{ "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "a", EntityType.BODY), BodyType.SHEET), EntityType.EDGE), vector(0, 10, 0) * millimeter), "continuity" : GeometricContinuity.G1 }, { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "b", EntityType.BODY), BodyType.SHEET), EntityType.EDGE), vector(10, 10, 5) * millimeter), "continuity" : GeometricContinuity.G1 }, { "entities" : qUnion([qOwnedByBody(qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), qOwnedByBody(qBodyType(qCreatedBy(id + "s2", EntityType.BODY), BodyType.WIRE), EntityType.EDGE)]), "continuity" : GeometricContinuity.G0 }], "surfaceOperationType" : NewSurfaceOperationType.NEW });
    return { "faces" : fillProbe(context, qOwnedByBody(qBodyType(qCreatedBy(id + "fill1", EntityType.BODY), BodyType.SHEET), EntityType.FACE)) };
}

